<?php require 'includes/bootstrap.php';if(me())go('dashboard.php');$errors=[];$dev='';if($_SERVER['REQUEST_METHOD']==='POST'){check_csrf();$email=strtolower(trim($_POST['email']??''));$name=trim($_POST['name']??'');$pass=$_POST['password']??'';if(!filter_var($email,FILTER_VALIDATE_EMAIL))$errors[]='Use a valid email.';if(strlen($name)<3)$errors[]='Enter your full name.';if(!valid_password($pass))$errors[]='Password needs 12+ characters with upper, lower, number and symbol.';$s=$pdo->prepare('SELECT id FROM users WHERE email=?');$s->execute([$email]);if($s->fetch())$errors[]='That email is already registered.';if(!$errors){$token=bin2hex(random_bytes(32));$qr=bin2hex(random_bytes(32));$s=$pdo->prepare('INSERT INTO users(email,password_hash,full_name,verify_hash,verify_expires,qr_token) VALUES(?,?,?, ?,DATE_ADD(NOW(),INTERVAL 30 MINUTE),?)');$s->execute([$email,password_hash($pass,PASSWORD_DEFAULT),$name,hash('sha256',$token),$qr]);$uid=(int)$pdo->lastInsertId();if(!empty($_POST['camera_data'])){$photo=save_photo($_POST['camera_data'],$uid);if($photo){$pdo->prepare('UPDATE users SET photo_path=? WHERE id=?')->execute([$photo,$uid]);}}$link=url('verify.php?token='.$token);$sent=send_mail_safe($email,'Verify your SecureFin account',"Open this link within 30 minutes:\n$link");audit('registered',$uid,$sent?'mail sent':'mail unavailable');if($config['dev_show_tokens'])$dev=$link;note($sent?'Check your email for the verification link.':'Email could not be sent. Ask the administrator to configure SMTP/mail.');if(!$dev)go('login.php');}}
$pageTitle='Register';require 'includes/header.php';?><section class="card narrow"><h1>Create account</h1><?php foreach($errors as $x):?><p class="error"><?=e($x)?></p><?php endforeach?><?php if($dev):?><p class="notice">Development verification link: <a href="<?=e($dev)?>">verify account</a></p><?php endif?><form method="post"><input type="hidden" name="csrf" value="<?=csrf()?>"><label>Full name<input name="name" required value="<?=e($_POST['name']??'')?>"></label><label>Email<input type="email" name="email" required value="<?=e($_POST['email']??'')?>"></label><label>Password<input type="password" name="password" required minlength="12" autocomplete="new-password"></label><div class="camera"><video id="camera" autoplay playsinline></video><canvas id="snapshot" hidden></canvas><input type="hidden" name="camera_data" id="camera-data"><button type="button" class="button ghost" id="start-camera">Start live camera</button><button type="button" class="button ghost" id="take-photo">Capture photo</button><small>Optional. Camera requires HTTPS and your permission.</small></div><button class="button">Register securely</button></form></section><?php require 'includes/footer.php';?>
